INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2000,2000,0,0,0,0,0,0,'0',256,NULL,0,0,0,0,NULL,NULL,0,0,0,0,'default',0,'','textmedia',0,0,'','',0,'This page is a TYPO3 page.',0,'','','','<p>Every sentence here was written in a TYPO3 page tree and delivered as JSON by <strong>tca-api-headless</strong>: composed pages, typed content elements, navigation and SEO meta for any frontend. Each proof shows the request, the JSON and the TypeScript type behind a section.</p><pre><code>composer require maikschneider/tca-api-headless</code></pre>',0,0,NULL,NULL,0,0,0,2,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2001,2000,0,0,0,0,0,0,'0',256,NULL,0,0,0,0,NULL,NULL,0,0,0,0,'default',1,'','text',0,0,'','',0,'Editors stay in TYPO3',0,'','','','<p>Page tree, backend layouts, content elements and translations work the way editors know them. Nothing changes in the backend: the frontend receives the page as it was composed, as data instead of HTML.</p><p>Start with the <a href=\"t3://page?uid=2001\">quick start</a>, or see the same API render the <a href=\"t3://page?uid=3000\" title=\"A fictional bicycle workshop\">Kettenblatt specimen site</a>.</p>',0,0,NULL,NULL,0,0,0,2,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2002,2000,0,0,0,0,0,0,'0',256,NULL,0,0,0,0,NULL,NULL,0,0,0,0,'default',2,'','table',0,0,'','',0,'What a response carries',0,'','','','Field|What the frontend gets\nregions|Content elements, grouped by the column identifiers of the backend layout\nbodytext|Portable Text, list items or table rows, depending on the content type\nheader_link|A link object with href, target and title\nmeta|Robots, a canonical URL in the request language and a schema.org WebPage\nog_image|An absolute URL to the processed social image\nnavigation|A menu tree with absolute URLs, limited by a depth setting\n?path=|The page uid behind a URL path, in the request language',0,0,NULL,NULL,0,0,0,2,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,1,0,NULL,0,'','','',0,0);
