INSERT INTO `tt_content` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `rowDescription`, `editlock`, `sys_language_uid`, `l18n_parent`, `l10n_source`, `l10n_state`, `l18n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `frame_class`, `colPos`, `table_caption`, `CType`, `categories`, `layout`, `space_before_class`, `space_after_class`, `date`, `header`, `header_layout`, `header_position`, `header_link`, `subheader`, `bodytext`, `image`, `assets`, `imagewidth`, `imageheight`, `imageorient`, `imageborder`, `image_zoom`, `imagecols`, `pages`, `recursive`, `media`, `records`, `sectionIndex`, `linkToTop`, `pi_flexform`, `selected_categories`, `category_field`, `bullets_type`, `cols`, `table_class`, `table_delimiter`, `table_enclosure`, `table_header_position`, `table_tfoot`, `file_collections`, `filelink_size`, `filelink_sorting`, `filelink_sorting_direction`, `target`, `uploads_description`, `uploads_type`) VALUES (2090,2000,0,0,0,0,0,0,'0',128,NULL,0,0,0,0,NULL,NULL,0,0,0,0,'default',3,NULL,'text',0,0,'','',0,'From composer to the first response',0,'','','','<ol><li>Require the package: <code>composer require maikschneider/tca-api-headless</code></li><li>Add the site set <code>maikschneider/tca-api-headless</code> to the dependencies in the site\'s <code>config.yaml</code>.</li><li>Give the columns of your backend layout identifiers such as <code>main</code>. They become the region names.</li><li>Request a page: <code>curl https://example.org/_api/headless_pages/1</code></li><li>Write the OpenAPI document of the site and generate types from it:</li></ol><pre><code>vendor/bin/typo3 tca-api:openapi main --output openapi.json\nbunx openapi-typescript openapi.json -o src/api/schema.d.ts</code></pre><p>tca-api-headless is in development. It needs TCA API 2.4 and TYPO3 13.4 or 14.3.</p>',0,0,NULL,NULL,0,0,0,2,NULL,0,0,NULL,1,0,NULL,NULL,'',0,0,'',124,0,0,0,NULL,0,'','','',0,0);
